import{_ as t,c as s,o as r,j as e,a as l}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"周易口訣義","description":"周易口訣義 - 周易口訣義","frontmatter":{"title":"周易口訣義","description":"周易口訣義 - 周易口訣義"},"headers":[],"relativePath":"classics/koujueyi/001.md","filePath":"classics/koujueyi/001.md"}'),o={name:"classics/koujueyi/001.md"};function n(i,a,c,d,p,u){return r(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易口訣義",tabindex:"-1"},[l("周易口訣義 "),e("a",{class:"header-anchor",href:"#周易口訣義","aria-label":"Permalink to “周易口訣義”"},"​")],-1),e("p",null,"欽定四庫全書經部一提要易類",-1),e("p",null,"臣 等謹案：",-1),e("p",null,"周易口訣義六卷，唐史徵撰。崇文總目曰：「河南史徵，不詳何代人。」晁公武讀書志曰：「田氏以為魏鄭公撰，誤。」陳振孫曰：「三朝史志有其書，非唐，則五代人避諱作證字。」宋史藝文志又作「史文徽」，蓋以「徽」、徵二字相近而訛。別本作「史之徵」，則又以之、文二字相近而訛耳。今定為史徵，從永樂大典；定為唐人，從朱彝尊經義考也。永樂大典載徵自序雲：「但舉宏機，纂其樞要，先以王注為宗，後約孔疏為理。」故崇文總目及晁氏讀書志皆以為直抄註疏，以便講習，考之實不盡然。如乾彖引周氏說，大象引宋衷說，屯彖引李氏說，訟彖引周氏說，師彖引陸績說，六五引莊氏說，謙六五引張氏說，觀大象引鄭眾說，賁大象引王廙說，頤大象引荀爽說，坎大象引莊氏說，上六引虞氏說，鹹大象引何妥說，萃彖引周弘正說，升彖引褚氏說，井大象引何妥說，革彖引宋衷說，鼎彖引何妥說，震九四引鄭眾說，漸彖引褚氏說，大象引侯果說，困大象引周弘正說，兌大象引鄭眾說，漸九五引陸績說。諸家原書，今並亡佚，惟孔疏及李鼎祚周易集解間存其說，是書所引，則多出二家所載之外。又如賁大象所引王氏說，頤大象所引荀爽說，雖屬集解所有，而其文互異。坎上六虞翻說，則集解刪削過略，此所載獨詳。蓋唐去六朝未遠，隋志所載諸家之書猶有存者，故徵得以旁搜博引。今閱年數百，舊籍多亡，則遺文緒論，無一非吉光片羽矣。近時惠棟作九經古義，餘蕭客葺古經解鉤沈，於唐以前經義，卑辭隻字，搜採至詳，而此書所載，均未之及，信為難得之秘本。雖其文義間涉拙滯，傅寫亦不免訛脫，而唐以前解易之書，子夏傅既屬偽撰，王應麟所輯鄭康成注，姚士磷所輯陸績、幹寶二家注，亦非完書。其實存於今者，京房、王弼、孔穎達、李鼎祚四家及此書而五耳。固好古者所宜寶重也。自序作六卷，諸家書目並同。 今僅闕豫、隨、無妄、大壯、晉、睽、蹇、解、中孚八卦，所佚無多 ，仍編為六卷，存其舊焉。乾隆四十三年二月恭校上。",-1),e("p",null,"總纂官 臣 紀昀、 臣 陸錫熊、 臣 孫士毅。總校官 臣 陸費墀。",-1)])])}const f=t(o,[["render",n]]);export{_ as __pageData,f as default};
